CREATE OR REPLACE FUNCTION public.assign_task(_id uuid,_user uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tasks;BEGIN IF NOT public.has_permission('tasks.manage','edit') THEN RAISE EXCEPTION 'تعيين المهام للأدمن';END IF;PERFORM public._assert_reason(_reason);SELECT * INTO t FROM public.tasks WHERE id=_id FOR UPDATE;IF NOT FOUND OR t.status<>'open' OR NOT public.task_staff_active(_user) THEN RAISE EXCEPTION 'مهمة أو موظف غير صالح';END IF;IF t.visibility='financial' AND NOT(public.has_role(_user,'accountant') OR public.has_role(_user,'admin')) THEN RAISE EXCEPTION 'المهام المالية للمحاسب والأدمن';END IF;IF t.visibility='escalation' AND NOT(public.has_role(_user,'leasing_manager') OR public.has_role(_user,'admin')) THEN RAISE EXCEPTION 'التصعيد لمدير التأجير';END IF;IF public.has_role(_user,'sales_agent') AND (t.visibility<>'operational' OR t.entity_type IN('contract','installment')) THEN RAISE EXCEPTION 'هذه المهمة غير مسموحة للمبيعات';END IF;UPDATE public.tasks SET assignee_user_id=_user,updated_at=now() WHERE id=t.id;PERFORM public._safety_audit('TASK_ASSIGNED','tasks',t.id::text,to_jsonb(t),(SELECT to_jsonb(x) FROM public.tasks x WHERE id=t.id),_reason);END $$;
CREATE OR REPLACE FUNCTION public.create_task(_title text,_type text,_user uuid,_due timestamptz,_entity text,_entity_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid;valid boolean:=false;BEGIN IF NOT public.has_permission('tasks.manage','edit') THEN RAISE EXCEPTION 'إنشاء مهام الفريق للأدمن';END IF;PERFORM public._assert_reason(_reason);IF length(btrim(_title)) NOT BETWEEN 3 AND 200 OR length(_type)>64 OR _due IS NULL OR _entity NOT IN('unit','party','opportunity','booking','contract','installment') THEN RAISE EXCEPTION 'بيانات مهمة غير صالحة';END IF;CASE _entity WHEN 'unit' THEN SELECT EXISTS(SELECT 1 FROM public.units WHERE id=_entity_id) INTO valid;WHEN 'party' THEN SELECT EXISTS(SELECT 1 FROM public.parties WHERE id=_entity_id) INTO valid;WHEN 'opportunity' THEN SELECT EXISTS(SELECT 1 FROM public.opportunities WHERE id=_entity_id) INTO valid;WHEN 'booking' THEN SELECT EXISTS(SELECT 1 FROM public.bookings WHERE id=_entity_id) INTO valid;WHEN 'contract' THEN SELECT EXISTS(SELECT 1 FROM public.contracts WHERE id=_entity_id) INTO valid;WHEN 'installment' THEN SELECT EXISTS(SELECT 1 FROM public.installments WHERE id=_entity_id) INTO valid;END CASE;IF NOT valid THEN RAISE EXCEPTION 'السجل المرتبط غير موجود';END IF;INSERT INTO public.tasks(title,type,due_at,entity_type,entity_id,created_by,visibility) VALUES(btrim(_title),_type,_due,_entity,_entity_id,auth.uid(),CASE WHEN _entity='installment' THEN 'financial' ELSE 'operational' END) RETURNING id INTO k;IF _user IS NOT NULL THEN PERFORM public.assign_task(k,_user,_reason);END IF;PERFORM public._safety_audit('TASK_CREATED','tasks',k::text,NULL,(SELECT to_jsonb(t) FROM public.tasks t WHERE id=k),_reason);RETURN k;END $$;
CREATE OR REPLACE FUNCTION public.team_followup_view(_view text,_offset integer DEFAULT 0,_limit integer DEFAULT 25) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;cap text;BEGIN SELECT required_capability INTO cap FROM public.team_saved_views WHERE code=_view;IF cap IS NULL OR NOT(public.has_permission(cap,'view') OR public.has_permission(cap,'own')) THEN RAISE EXCEPTION 'العرض غير مسموح لدورك';END IF;IF _view='overdue' AND NOT public.finance_can_read() THEN RAISE EXCEPTION 'البيانات المالية غير مسموحة';END IF;WITH f AS(SELECT o.id,'opportunity'::text AS entity_type,'متابعة الفرصة'::text AS title,coalesce(o.next_action_at,o.created_at) AS due_at FROM public.opportunities o WHERE _view IN('no_followup','untouched_targets') AND o.outcome IS NULL AND o.stage<>'won' AND (public.has_permission('tasks.manage','view') OR o.owner_user_id=auth.uid()) AND ((_view='no_followup' AND (o.next_action_at IS NULL OR o.next_action_at<now())) OR (_view='untouched_targets' AND o.source='target_list' AND NOT EXISTS(SELECT 1 FROM public.opportunity_activities a WHERE a.opportunity_id=o.id))) UNION ALL SELECT b.id,'booking','حجز ينتهي اليوم',b.expires_at FROM public.bookings b WHERE _view='holds_today' AND b.status='pending' AND b.archived_at IS NULL AND (b.expires_at AT TIME ZONE 'Asia/Riyadh')::date=(now() AT TIME ZONE 'Asia/Riyadh')::date AND (public.has_permission('tasks.manage','view') OR EXISTS(SELECT 1 FROM public.opportunities o WHERE o.booking_id=b.id AND o.owner_user_id=auth.uid())) UNION ALL SELECT t.entity_id,t.entity_type,t.title,t.due_at FROM public.tasks t WHERE ((_view='overdue' AND t.type='installment_due' AND public.metrics_is_overdue((t.due_at AT TIME ZONE 'Asia/Riyadh')::date,(now() AT TIME ZONE 'Asia/Riyadh')::date,(SELECT grace_days FROM public.app_settings WHERE id=1))) OR (_view='renewals' AND t.type='contract_renewal')) AND t.status='open' AND public.task_can_read(t)),p AS(SELECT * FROM f ORDER BY due_at,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM p),'[]'),'count',(SELECT count(*) FROM f),'as_of',now()) INTO result;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.log_party_activity(_party uuid,_type public.opportunity_activity_type,_outcome public.opportunity_activity_outcome,_notes text,_next text,_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid;o uuid;BEGIN IF NOT public.can_read_party_contact(_party) OR NOT(public.has_permission('opportunities.write','own') OR public.has_permission('opportunities.write','edit')) THEN RAISE EXCEPTION 'التواصل لعملائك فقط';END IF;IF length(coalesce(_notes,''))>2000 OR (_at IS NOT NULL AND _next IS NULL) THEN RAISE EXCEPTION 'بيانات متابعة غير صالحة';END IF;SELECT id INTO o FROM public.opportunities WHERE party_id=_party AND outcome IS NULL AND stage<>'won' AND (owner_user_id=auth.uid() OR public.has_permission('opportunities.write','edit')) ORDER BY created_at DESC LIMIT 1;IF o IS NOT NULL THEN PERFORM public.log_opportunity_activity(o,_type,_outcome,_notes,_next,_at);RETURN o;END IF;INSERT INTO public.party_activities(party_id,activity_type,outcome,notes,next_action,next_action_at,actor_id) VALUES(_party,_type,_outcome,_notes,_next,_at,auth.uid()) RETURNING id INTO k;IF _at IS NOT NULL THEN PERFORM public._task_upsert('party-followup:'||k,'متابعة العميل','party_followup',auth.uid(),_at,'party',_party);END IF;PERFORM public._safety_audit('PARTY_ACTIVITY','party_activities',k::text,NULL,jsonb_build_object('party_id',_party,'type',_type,'next_action_at',_at),'تسجيل تواصل العميل');RETURN k;END $$;
CREATE OR REPLACE FUNCTION public.activity_page(_party uuid DEFAULT NULL,_opportunity uuid DEFAULT NULL,_offset integer DEFAULT 0,_limit integer DEFAULT 25) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.parties p WHERE p.id=coalesce(_party,(SELECT party_id FROM public.opportunities WHERE id=_opportunity)) AND public.can_read_party_contact(p.id)) THEN RAISE EXCEPTION 'سجل التواصل غير مسموح';END IF;RETURN(WITH f AS(SELECT a.id,a.activity_type,a.outcome,a.notes,a.next_action,a.next_action_at,a.actor_id,a.created_at FROM public.opportunity_activities a JOIN public.opportunities o ON o.id=a.opportunity_id WHERE ((_opportunity IS NOT NULL AND o.id=_opportunity) OR (_party IS NOT NULL AND o.party_id=_party)) AND (o.owner_user_id=auth.uid() OR public.has_permission('opportunities.write','edit') OR public.has_role(auth.uid(),'accountant')) UNION ALL SELECT a.id,a.activity_type,a.outcome,a.notes,a.next_action,a.next_action_at,a.actor_id,a.created_at FROM public.party_activities a WHERE _party=a.party_id AND public.can_read_party_contact(a.party_id)),p AS(SELECT f.*,pr.display_name AS actor_name FROM f LEFT JOIN public.profiles pr ON pr.user_id=f.actor_id ORDER BY f.created_at DESC,f.id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM p),'[]'),'count',(SELECT count(*) FROM f)) );END $$;
REVOKE ALL ON FUNCTION public.assign_task(uuid,uuid,text),public.create_task(text,text,uuid,timestamptz,text,uuid,text),public.team_followup_view(text,integer,integer),public.log_party_activity(uuid,public.opportunity_activity_type,public.opportunity_activity_outcome,text,text,timestamptz),public.activity_page(uuid,uuid,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.assign_task(uuid,uuid,text),public.create_task(text,text,uuid,timestamptz,text,uuid,text),public.team_followup_view(text,integer,integer),public.log_party_activity(uuid,public.opportunity_activity_type,public.opportunity_activity_outcome,text,text,timestamptz),public.activity_page(uuid,uuid,integer,integer) TO authenticated;
SELECT to_regprocedure('public.team_followup_view(text,integer,integer)') IS NOT NULL AS followup_ready;